const TOP:u64=16777215;const H:u64=8388608;const Q:u64=4194304;const T:u64=12582912;
struct Model{a:[[u64;3];4],ctx:usize}
impl Model{fn new()->Self{Self{a:[[1;3];4],ctx:3}}fn cdf(&self)->[u64;4]{let [a,b,c]=self.a[self.ctx];[0,a,a+b,a+b+c]}fn update(&mut self,t:usize){let a=&mut self.a[self.ctx];a[t]+=1;if a.iter().sum::<u64>()>=4096{for x in a{*x=(*x+1)>>1}}self.ctx=t}}
struct Bits{out:Vec<u8>,v:u8,k:u8}
impl Bits{fn bit(&mut self,x:u8){self.v=(self.v<<1)|x;self.k+=1;if self.k==8{self.out.push(self.v);self.v=0;self.k=0}}fn emit(&mut self,x:u8,p:&mut usize){self.bit(x);while *p>0{self.bit(1-x);*p-=1}}}
pub fn encode(b:&[u8])->Vec<u8>{let(mut lo,mut hi,mut p)=(0,TOP,0usize);let mut m=Model::new();let mut bits=Bits{out:(b.len() as u32).to_be_bytes().to_vec(),v:0,k:0};
for &x in b{for j in (0..6).rev(){let t=(x as u64/3u64.pow(j)%3) as usize;let c=m.cdf();let r=hi-lo+1;hi=lo+r*c[t+1]/c[3]-1;lo+=r*c[t]/c[3];loop{if hi<H{bits.emit(0,&mut p)}else if lo>=H{bits.emit(1,&mut p);lo-=H;hi-=H}else if lo>=Q&&hi<T{p+=1;lo-=Q;hi-=Q}else{break}lo*=2;hi=hi*2+1}m.update(t)}}p+=1;bits.emit(if lo<Q{0}else{1},&mut p);if bits.k>0{bits.out.push(bits.v<<(8-bits.k))}bits.out}
pub fn decode(b:&[u8],limit:usize)->Result<Vec<u8>,&'static str>{if b.len()<5{return Err("range header")}let n=u32::from_be_bytes(b[..4].try_into().unwrap()) as usize;if n>limit{return Err("limit")}let mut pos=32;let mut bit=||{let i=pos;pos+=1;if i>=b.len()*8+24{return Err("truncated range")}Ok(if i>=b.len()*8{0}else{((b[i/8]>>(7-i%8))&1) as u64})};let(mut lo,mut hi,mut v)=(0,TOP,0);for _ in 0..24{v=v*2+bit()?}let mut m=Model::new();let mut out=Vec::with_capacity(n);for _ in 0..n{let mut x=0;for _ in 0..6{if v<lo||v>hi{return Err("range value")}let c=m.cdf();let r=hi-lo+1;let s=((v-lo+1)*c[3]-1)/r;let t=if s<c[1]{0}else if s<c[2]{1}else{2};hi=lo+r*c[t+1]/c[3]-1;lo+=r*c[t]/c[3];loop{if hi<H{}else if lo>=H{lo-=H;hi-=H;v-=H}else if lo>=Q&&hi<T{lo-=Q;hi-=Q;v-=Q}else{break}lo*=2;hi=hi*2+1;v=v*2+bit()?}m.update(t);x=x*3+t}if x>255{return Err("invalid byte")}out.push(x as u8)}Ok(out)}
